<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;
use App\Modules\CommercialRental\Services\CommercialRentalProviderService;
final class CommercialRentalProviderController extends Controller{private CommercialRentalProviderService$s;private Authorization$a;public function __construct(){$this->s=new CommercialRentalProviderService();$this->a=new Authorization();}private function ok(string$p,string$r='/commercial-rentals'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException$e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->ok('commercial_rental.providers.view'))return;$this->view('CommercialRental::Providers.index',['title'=>'Rental Providers','providers'=>$this->s->all((int)Auth::tenantId())]);}public function create():void{if(!$this->ok('commercial_rental.providers.create','/commercial-rentals/providers'))return;$this->view('CommercialRental::Providers.create',['title'=>'Add Rental Provider']);}public function store():void{if(!$this->ok('commercial_rental.providers.create','/commercial-rentals/providers'))return;try{$this->s->create((int)Auth::tenantId(),$_POST,(int)Auth::id());flash('success','Commercial rental provider created.');redirect('/commercial-rentals/providers');}catch(Throwable$e){$this->view('CommercialRental::Providers.create',['title'=>'Add Rental Provider','error'=>$e->getMessage(),'old'=>$_POST]);}}public function show(int$id):void{if(!$this->ok('commercial_rental.providers.view','/commercial-rentals/providers'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Providers.show',['title'=>$r['business_name'],'record'=>$r]);}public function edit(int$id):void{if(!$this->ok('commercial_rental.providers.edit','/commercial-rentals/providers'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('CommercialRental::Providers.edit',['title'=>'Edit Rental Provider','record'=>$r]);}public function update(int$id):void{if(!$this->ok('commercial_rental.providers.edit','/commercial-rentals/providers'))return;try{$this->s->update((int)Auth::tenantId(),$id,$_POST,(int)Auth::id());flash('success','Provider updated.');redirect('/commercial-rentals/providers/'.$id);}catch(Throwable$e){$this->view('CommercialRental::Providers.edit',['title'=>'Edit Rental Provider','record'=>$_POST,'error'=>$e->getMessage()]);}}public function destroy(int$id):void{if(!$this->ok('commercial_rental.providers.delete','/commercial-rentals/providers'))return;try{$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Provider deleted.');}catch(Throwable$e){flash('error',$e->getMessage());}redirect('/commercial-rentals/providers');}}
